import{_ as i,l as n,o as t,c as d,v as e,p as l,x as r,d as s,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"QuaRot","description":"","frontmatter":{"title":"QuaRot","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quarot.md","filePath":"llm/quarot.md","lastUpdated":1789023840000}'),p={name:"llm/quarot.md"};function u(b,a,c,Q,A,P){const o=n("Mermaid");return t(),d("div",null,[a[1]||(a[1]=e('<h1 id="quarot" tabindex="-1">QuaRot <a class="header-anchor" href="#quarot" aria-label="Permalink to &quot;QuaRot&quot;">​</a></h1><div class="epigraph"><p>旋转不改浮点网络的函数，却能把卡在少数通道上的异常值打散到所有维度；打散之后，权重、激活与 KV 才可能同时走进 4-bit 格子，而不必给尖峰通道开小灶。</p><footer>—— Ashkboos 等，QuaRot: Outlier-Free 4-Bit Inference in Rotated LLMs，NeurIPS 2024</footer></div><p>Saleh Ashkboos、Amirkeivan Mohtashami、Maximilian L. Croci、Bo Li、Pashmina Cameron、Martin Jaggi、Dan Alistarh、Torsten Hoefler 与 James Hensman 的 NeurIPS 2024 论文（arXiv:2404.00456）把量化里的异常值问题收成 <strong>正交变换下的计算不变性</strong>。前作 SliceGPT 已经指出：RMSNorm 加线性层允许插入 \\(QQ^\\top=I\\) 而不改函数。QuaRot 用随机化 Hadamard 把隐空间转一下，让通道尖峰变成各向更匀的坐标，再对旋转后的权重做 GPTQ、对激活与 KV 做普通取整，从而把 <strong>W4A4KV4</strong> 写成可引用的推理形状。它不是新的码本，也不是再搜一套逐通道 \\(s\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>W4A16 已经能靠 GPTQ / AWQ 保住生成质量，因为激活仍是半精度，误差只发生在 \\(W\\) 上。一旦激活也进 4-bit，通道异常值会把逐 token 尺度绑死，等效比特远低于 4，困惑度塌掉。SmoothQuant 把难度迁到权重，对 8-bit 够用；迁到 4-bit 时，权重侧也会饱和。LLM.int8() 式分流在 4-bit 下更不划算：例外通道一多，整数核的面积消失。</p><p>需要一种变换：浮点函数不变，量化网格却看到更同质的坐标。随机正交阵在理论上能把能量摊开（不相干性），但稠密 \\(Q\\) 的乘本身吃掉加速。Hadamard 提供一类结构化正交：乘法是加减与缩放，能写成 \\(O(d\\log d)\\) 的快速变换，也容易融进相邻线性层。问题变成：在 Transformer 的哪些位置插入 Hadamard，才能既打散激活尖峰，又不在 decode 每步付一次满矩阵乘。</p><h3 id="计算不变性允许插入正交阵" tabindex="-1">计算不变性允许插入正交阵 <a class="header-anchor" href="#计算不变性允许插入正交阵" aria-label="Permalink to &quot;计算不变性允许插入正交阵&quot;">​</a></h3><p>RMSNorm 按 token 的 \\(\\ell_2\\) 缩放。正交 \\(Q\\) 保持欧氏范数，因而</p> \\[\\mathrm{RMSNorm}(xQ)=\\mathrm{RMSNorm}(x)\\,Q, \\]<p>于是 \\(\\mathrm{RMSNorm}(x)W=\\mathrm{RMSNorm}(xQ)\\,(Q^\\top W)\\)。\\(Q\\) 可以吸进下一层权重，\\(Q^\\top\\) 可以吸进上一层。残差两端必须转同一组基，否则捷径与块输出不在同一坐标。LayerNorm 含逐维仿射，不变性更窄，往往要先把 \\(\\gamma\\) 处理掉。原文的对象主要是 LLaMA 一类 RMSNorm 骨干；把同一套旋转抄到带偏置、带 LayerNorm 的 OPT 上，要另做吸收，不能直接引用 LLaMA 表格。</p><p><span class="marginnote">QuaRot 的「无异常值」是旋转之后坐标上的经验观察，不是证明模型不再有重尾。尖峰被摊到许多维，逐维 max 下降，共享尺度才变得可 4-bit。可视化里「通道尖峰消失」与「信息被毁掉」不是一回事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线：在嵌入、注意力投影、MLP 上下投影等可吸收位置插入随机化 Hadamard（常带随机符号对角，以免结构化正交留下周期性伪影），把对应权重改写成旋转后的矩阵，再跑 GPTQ 一类权重量化。在线：对无法完全吸收的激活——典型是注意力里的值、MLP 的中间激活——在量化前做一次快速 Hadamard，反量化后乘回，或把逆变换融进下一层已旋转的权重。KV 缓存在旋转坐标里量化，读取时与查询处在同一基。</p><p>权重走 4-bit GPTQ（或 RTN，质量较差），激活与 KV 走逐 token / 分组 4-bit 取整。主声称形状是 <strong>W4A4KV4</strong>：权重、激活、键值缓存同时 4-bit。LLaMA-2-70B 上论文报告该形状的困惑度相对 FP16 仍在可用区间，而未经旋转的 W4A4 会明显坏掉。零样本常识任务用来表明不是只刷 WikiText。加速来自 4-bit GEMM 与 4-bit KV 带宽；在线 Hadamard 是必须计入的税，不能只报量化 GEMM。</p>',14)),(t(),l(h,null,{default:r(()=>[m(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%9A%90%E7%8A%B6%E6%80%81%22%5D%20--%3E%20H%5B%22Hadamard%20%E6%97%8B%E8%BD%AC%22%5D%0A%20%20H%20--%3E%20QX%5B%224-bit%20%E6%BF%80%E6%B4%BB%22%5D%0A%20%20W%5B%22%E5%B7%B2%E5%90%B8%E6%94%B6%20Q%20%E7%9A%84%E6%9D%83%E9%87%8D%22%5D%20--%3E%20QW%5B%22GPTQ%204-bit%22%5D%0A%20%20QX%20--%3E%20GEMM%5B%22W4A4%20GEMM%22%5D%0A%20%20QW%20--%3E%20GEMM%0A%20%20GEMM%20--%3E%20KV%5B%224-bit%20KV%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20KV%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="在线旋转与离线融合不是同一笔开销" tabindex="-1">在线旋转与离线融合不是同一笔开销 <a class="header-anchor" href="#在线旋转与离线融合不是同一笔开销" aria-label="Permalink to &quot;在线旋转与离线融合不是同一笔开销&quot;">​</a></h3><p>能吸进权重的 Hadamard 在推理图里消失，只留下量化 GEMM。不能吸收的位置每步都要做快速变换。decode 时激活行数等于 batch，Hadamard 的绝对时间小，但 4-bit 核本身也短，税的占比上升。prefill 长序列上 GEMM 占主导，税被摊薄。论文若报端到端加速，应写清哪些层是在线旋转。实现若漏掉随机符号或残差两侧基不一致，会在「已经旋转」的假象下量化一个错误的函数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不相干性：若 \\(W\\) 在标准基下有少数巨大列，量化误差被这些列主导。正交变换后，Frobenius 能量相同，但 \\(\\max |W&#39;_{ij}|\\) 相对下降，逐元素均匀网格的最坏误差变小。激活同理。这与 SmoothQuant 的对角 \\(s\\) 不同：对角只重新分配各通道的尺度，不混合通道；Hadamard 混合通道，把尖峰变成多维上的中等幅度。混合是双刃剑：对量化友好，对「某通道有语义」的解释不友好——量化之后更难做通道级诊断。</p><p>GPTQ 发生在旋转后的权重上。Hessian 来自旋转后的校准激活，补偿方向也在新基里。先 GPTQ 再旋转，或先旋转却用未旋转的校准，都会破坏论文的误差账。KV 4-bit 的合法性同样依赖旋转：未经旋转的 K 通道异常值已被 KIVI 一类工作指出；QuaRot 用同一套基去处理权重、激活与 KV，避免三套坐标系。</p><p><span class="marginnote">随机 Hadamard 不是学出来的最优旋转。它的优点是无需校准优化、可复现、能快速变换。SpinQuant 后来把可学习旋转写成同一条故事的下一句；不要把 QuaRot 的随机阵写成已经最优。</span></p><h3 id="与对角平滑、与不相干处理的谱系" tabindex="-1">与对角平滑、与不相干处理的谱系 <a class="header-anchor" href="#与对角平滑、与不相干处理的谱系" aria-label="Permalink to &quot;与对角平滑、与不相干处理的谱系&quot;">​</a></h3><p>SmoothQuant / OS+ 是对角等价变换，通道轴仍在。QuIP 的不相干处理也用正交阵，但主战场是 2-bit <strong>权重</strong>，激活常仍较高精度。QuaRot 把旋转对准 <strong>激活与 KV 的 4-bit</strong>，权重 4-bit 是配套而不是唯一卖点。引用时写清位宽三元组 \\((W,A,\\mathrm{KV})\\)。把 QuaRot 说成「又一种 GPTQ」会丢掉旋转这一半；把 QuIP# 的 2-bit 权重数字写进这篇的 W4A4 表，是错赛道。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="w4a4-核与-hadamard-核都要有" tabindex="-1">W4A4 核与 Hadamard 核都要有 <a class="header-anchor" href="#w4a4-核与-hadamard-核都要有" aria-label="Permalink to &quot;W4A4 核与 Hadamard 核都要有&quot;">​</a></h3><p>没有 4-bit 激活 GEMM 时，W4A4 只是精度实验。没有融合或快速 Hadamard 时，在线旋转会吃掉带宽收益。分组大小、对称与否、是否对 <code>lm_head</code> 保持高精度，都会移动困惑度。LLaMA-2 上的表格不能直接当 LLaMA-3 / Qwen 的承诺：RMSNorm 结构相近，但通道异常值形态与残差尺度不同，要重跑旋转 + GPTQ。GQA 下 KV 头更少，KV4 的显存收益相对更大，也让量化误差更难被多头平均掉。</p><p>残差、RoPE、注意力缩放与旋转的交换顺序必须按论文实现。RoPE 作用在旋转前还是旋转后的坐标，会改变「查询与键是否仍在同一相对位置编码」；抄错顺序会出现「PPL 还行、长上下文针测崩」的分裂。校准句数量对 GPTQ 半段敏感，对 Hadamard 本身不敏感——旋转是随机的，不是从校准里学的。因此「少校准」不是这篇相对 OmniQuant 的卖点，少的是旋转学习，不是权重量化校准。</p><p><span class="marginnote">出处：Ashkboos et al.，<em>QuaRot: Outlier-Free 4-Bit Inference in Rotated LLMs</em>，NeurIPS 2024（arXiv:2404.00456）。计算不变性的线性代数来自 SliceGPT 一系，量化合同是这篇自己的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>QuaRot 用可吸收的 Hadamard 旋转打散通道异常值，使 W4A4KV4 成为可引用的推理形状。</li><li>浮点函数在正交变换下不变；量化网格看到更同质的坐标。</li><li>权重量化仍常走 GPTQ；旋转不替代 Hessian 补偿。</li><li>在线 Hadamard 是税；加速绑定 4-bit 核与融合实现。</li><li>出处：Ashkboos et al.，NeurIPS 2024。</li></ul>',15))])}const T=i(p,[["render",u]]);export{E as __pageData,T as default};
